solutionCode:
pub fn etiqueta(pedido: i32, qtd: i32) -> String {
    format!("pedido {pedido} x {qtd}")
}

testsCode:
use desafio::etiqueta;

#[test]
fn testa_a_etiqueta_do_pedido_sete() {
    assert_eq!(etiqueta(7, 3), "pedido 7 x 3");
}

#[test]
fn testa_a_etiqueta_do_pedido_doze() {
    assert_eq!(etiqueta(12, 1), "pedido 12 x 1");
}
